async function inspectAssets() {
  const pages = figma.root.children;
  console.log("Pages:", pages.map(p => p.name));

  const compPage = pages.find(p => p.name.includes("Components"));
  const mediaPage = pages.find(p => p.name.includes("Media"));

  function getNodes(node) {
    let res = [];
    if (node.name) res.push({ id: node.id, name: node.name, type: node.type });
    if ('children' in node) {
      for (const child of node.children) {
        res = res.concat(getNodes(child));
      }
    }
    return res;
  }

  const compNodes = compPage ? getNodes(compPage) : [];
  const mediaNodes = mediaPage ? getNodes(mediaPage) : [];

  return {
    compNodes: compNodes.filter(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET' || n.type === 'FRAME' || n.type === 'INSTANCE'),
    mediaNodes: mediaNodes.filter(n => n.type === 'COMPONENT' || n.type === 'COMPONENT_SET' || n.type === 'FRAME' || n.type === 'INSTANCE' || n.name.startsWith("Logo") || n.name.startsWith("Icon") || n.name.startsWith("Photo") || n.name.startsWith("Avatar"))
  };
}
return await inspectAssets();

