  function createText(text, size, weight = "Regular", color = { r: 0.05, g: 0.05, b: 0.05 }, align = "LEFT") {
    const t = figma.createText();
    t.fontName = { family: "DM Sans", style: weight };
    t.characters = text;
    t.fontSize = size;
    t.fills = [{ type: 'SOLID', color }];
    t.textAlignHorizontal = align;
    return t;
  }

  // Create frames
  const frameNames = ['01_Sign_In', '02_Sign_Up', '03_Home', '04_Search', '05_Explore_Products', '06_Filter', '07_Product_Overview', '08_Product_Features', '09_Shopping_Cart', '10_Profile'];
  const frames = {};
  frameNames.forEach((n, i) => {
    const f = figma.createFrame();
    f.name = n;
    f.resize(375, 812);
    f.x = (i % 5) * 400;
    f.y = Math.floor(i / 5) * 900;
    workspacePage.appendChild(f);
    frames[n] = f;
  });

  return Object.keys(frames).map(k => ({ name: k, id: frames[k].id }));
}
return await buildInBatches();

